// Value types — almacenados directamente en el stack
int vidaMaxima = 100;
float velocidad = 5.5f;    // La 'f' es obligatoria para literales float
bool estaVivo = true;
char clase = 'G';           // Comillas simples para char

// Reference type — apunta a datos en el heap
string nombreJugador = "Héroe";

// Null solo es válido en reference types
string armaEquipada = null;  // ✔ válido
// int vida = null;          // ✘ Error de compilación

// Tipo implícito con var (C# infiere el tipo)
var puntuacion = 0;         // C# lo trata como int
var nombre = "Link";        // C# lo trata como string

// Constantes
const int MAX_ENEMIGOS = 50;
const float GRAVEDAD = 9.81f;

